-- Run after ux_pipeline_all.sql. Target: workspace.ux_telemetry.
-- GENERATED by databricks/designer/propose.py sql. Do not edit by hand: change the rules in propose.py.
-- AI DESIGNER inside Databricks: ai_gen drafts UI change proposals from the gold tables. Spark/Databricks SQL only.
-- ai_gen uses a model chosen and managed by Databricks (not selectable, not necessarily Claude) and has no output-format
-- enforcement. The raw reply and the exact evidence it saw are stored together; propose.py draft --from-ai-gen checks
-- every citation against that snapshot (value, n, element) and only then shows changes, as pending, for sign-off.
-- Run after ux_pipeline_all.sql. Calls a model once per run.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_design_proposals_raw AS
WITH ev AS (
  SELECT to_json(named_struct(
    'gold_version_comparison', (SELECT collect_list(struct(*)) FROM (SELECT concat_ws('|', 'gold_version_comparison', session_type, task_id, task_category) AS id, * FROM workspace.ux_telemetry.gold_version_comparison)),
    'gold_task_summary', (SELECT collect_list(struct(*)) FROM (SELECT concat_ws('|', 'gold_task_summary', session_type, app_version, task_id, task_category) AS id, * FROM workspace.ux_telemetry.gold_task_summary)),
    'gold_element_friction', (SELECT collect_list(struct(*)) FROM (SELECT concat_ws('|', 'gold_element_friction', session_type, app_version, uxid) AS id, * FROM workspace.ux_telemetry.gold_element_friction)),
    'gold_goal_summary', (SELECT collect_list(struct(*)) FROM (SELECT concat_ws('|', 'gold_goal_summary', session_type, app_version, goal_id, goal_cats) AS id, * FROM workspace.ux_telemetry.gold_goal_summary)),
    'gold_bot_behavior', (SELECT collect_list(struct(*)) FROM (SELECT concat_ws('|', 'gold_bot_behavior', session_type, behavior, app_version) AS id, * FROM workspace.ux_telemetry.gold_bot_behavior))
  )) AS evidence_json
)
SELECT current_timestamp() AS generated_at,
       'ai_gen' AS designer,
       evidence_json,
       ai_gen(concat('You are the UX designer on a usability study of a small analytics dashboard ("Taxi Ops") that also has a chat\nassistant. You propose concrete changes to the current design (v1), each backed by evidence from the study’s gold tables.\n\nRules:\n- Cite only evidence rows from the pack, by id. For each citation give the metric name exactly as it appears in that\n  row’s `metrics`, the value as given, and one of that row’s `n` fields with its value. A change with no valid citation\n  will be discarded.\n- Target exactly one dashboard element (one of `elements`, by its data-ux-id) or one assistant behavior (B1-B5).\n- Describe the change concretely enough to build: what the element looks like or does after the change.\n- Prefer v1-vs-v2 differences and rates with their n over single values. Do not claim statistical significance.\n- session_type ’simulated’ rows come from bots whose behavior encodes the study’s own hypotheses: they show a measurable\n  pattern, not that real people behave this way. Say so in the rationale when you rely on them. Prefer human rows when\n  they exist, and say when n is tiny.\n- Cite literature only by bib_key from `literature_verified`. If that list is empty, leave `literature` empty and do not\n  name papers or findings in the rationale.\n- `retest_metric` names the gold metric that should move if the change works, so it can be re-tested.\n- Propose at most 6 changes, the strongest first. A UX developer reviews each one before anything is built.\n\nReply with ONLY one JSON object, no prose and no code fence, in exactly this shape:\n{"summary": "one paragraph", "changes": [{"title": "...", "target_kind": "element or behavior", "target": "a data-ux-id or B1-B5", "change": "...", "evidence": [{"evidence_id": "an id from the rows", "metric": "a column of that row", "value": 0.0, "n_field": "an n_* column of that row", "n": 0}], "rationale": "...", "literature": [], "expected_effect": "...", "retest_metric": "..."}]}\n\nelements (data-ux-id): chart-bar, chart-line, chat-input, chat-launcher, chat-minimize, chat-selection-clear, chat-send, filter-borough, kpi-avg-fare, kpi-total-trips, menu-more\nelement notes: {"chart-bar": "bar chart: total trips by borough", "chart-line": "line chart: daily trips per borough (hovering and clicking points is possible)", "chat-input": "assistant prompt box", "chat-launcher": "button that opens the assistant", "chat-minimize": "button that minimizes the assistant", "chat-selection-clear": "clears the chart point selected for the assistant", "chat-send": "assistant send button", "filter-borough": "borough filter (select)", "kpi-avg-fare": "KPI card: average fare", "kpi-total-trips": "KPI card: total trips", "menu-more": "the ’...’ menu button in the header"}\nassistant answer types (behavior targets): {"B1": "answers to percent-difference questions between two boroughs", "B2": "answers to borough-specific averages and totals", "B3": "answers to highest / lowest day questions", "B4": "how the assistant is opened (identical in both versions since design revision 2)", "B5": "explanations of a chart point the user selected"}\nliterature_verified is empty: leave literature empty.\n\nEvidence rows grouped by table. Each row has an id (cite it as evidence_id); the n fields are the columns starting with n_. Rows:', ' ', evidence_json)) AS draft_json
FROM ev;
